export function youtubeId(value){let u;try{u=new URL(value)}catch{return null}if(!['http:','https:'].includes(u.protocol)||u.username||u.password)return null;const host=u.hostname.toLowerCase();let id=null;if(host==='youtu.be')id=u.pathname.split('/')[1];else if(['youtube.com','www.youtube.com','m.youtube.com','www.youtube-nocookie.com'].includes(host)){if(u.pathname==='/watch')id=u.searchParams.get('v');else if(/^\/(shorts|live|embed)\//.test(u.pathname))id=u.pathname.split('/')[2];}return /^[\w-]{11}$/.test(id||'')?id:null;}
export function publicIPv4(ip){if(isIP(ip)!==4)return false;const [a,b,c]=ip.split('.').map(Number);return !(a===0||a===10||a===127||a>=224||(a===100&&b>=64&&b<=127)||(a===169&&b===254)||(a===172&&b>=16&&b<=31)||(a===192&&(b===168||b===0||b===88&&c===99))||(a===198&&(b===18||b===19||b===51&&c===100))||(a===203&&b===0&&c===113));}
export function inputURL(value){const u=new URL(value);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||(u.port&&!['80','443'].includes(u.port)))throw Error('استخدم رابط فيديو HTTP أو HTTPS عامًا على منفذ عادي');if(u.hostname==='localhost'||u.hostname.endsWith('.localhost')||u.hostname.endsWith('.local')||u.hostname.includes(':')||isIP(u.hostname)&&!publicIPv4(u.hostname))throw Error('روابط الشبكات المحلية غير مدعومة');return u;}
// Pin every HTTP hop to a validated public IPv4 address; also revalidate redirects.
export async function openPublic(value,headers={},redirects=0){const u=inputURL(value);const records=await lookup(u.hostname,{family:4,all:true});if(!records.length||records.some(x=>!publicIPv4(x.address)))throw Error('العنوان لا يشير إلى خادم إنترنت عام');const address=records[0].address;const response=await new Promise((resolve,reject)=>{const r=(u.protocol==='https:'?https:http).request(u,{method:'GET',headers,lookup:(_h,opts,cb)=>opts?.all?cb(null,[{address,family:4}]):cb(null,address,4)},resolve);r.setTimeout(15000,()=>r.destroy(Error('انتهت مهلة مصدر الفيديو')));r.on('error',reject);r.end();});if([301,302,303,307,308].includes(response.statusCode)){response.destroy();if(redirects>=4||!response.headers.location)throw Error('إعادة توجيه غير صالحة');return openPublic(new URL(response.headers.location,u).href,headers,redirects+1);}if(response.statusCode<200||response.statusCode>=300){response.destroy();throw Error('تعذر الوصول إلى مصدر الفيديو ('+response.statusCode+')');}return {response,url:u.href};}
