export async function inspectDirect(value){const u=inputURL(value);const {response,url}=await openPublic(u.href);const type=String(response.headers['content-type']||'').toLowerCase();let bytes=Buffer.alloc(0);for await(const chunk of response){bytes=Buffer.concat([bytes,chunk]);if(bytes.length>=1024)break;}response.destroy();const text=bytes.toString('utf8').trimStart();if(text.startsWith('#EXTM3U'))return {url,format:'hls'};if(type.includes('text/html')||/^<!doctype|^<html/i.test(text))throw Error('هذا رابط صفحة؛ أدخل رابط الفيديو المباشر أو رابط يوتيوب');if(type.startsWith('video/')||bytes.subarray(4,8).toString()==='ftyp'||bytes.subarray(0,4).equals(Buffer.from([0x1a,0x45,0xdf,0xa3]))||bytes[0]===0x47)return {url,format:'auto'};throw Error('لم يُكتشف فيديو مباشر؛ جرّب رابط MP4 أو M3U8 صالحًا');}
