async function copy(id){try{await navigator.clipboard.writeText($(id).value);notice('تم نسخ الرابط');}catch{$(id).focus();$(id).select();notice('حدد الرابط وانسخه من الخانة');}}
function watch(){if(!authorized){notice('افتح رابط دعوة صالحًا للمشاهدة');return;}const v=$('video');player?.destroy();player=null;v.pause();v.removeAttribute('src');v.load();playing=true;if(currentSelection?.kind==='youtube'){v.hidden=true;$('youtube').hidden=false;$('youtube').src='https://www.youtube-nocookie.com/embed/'+currentSelection.videoId+'?playsinline=1&autoplay=1&origin='+encodeURIComponent(location.origin);return;}$('youtube').hidden=true;$('youtube').removeAttribute('src');v.hidden=false;if(window.Hls?.isSupported()){player=new Hls({maxBufferLength:20,backBufferLength:12});let tries=0;player.on(Hls.Events.MANIFEST_PARSED,()=>{v.play().catch(()=>notice('اضغط زر التشغيل داخل الفيديو'));});player.on(Hls.Events.ERROR,(_,d)=>{if(!d.fatal)return;if(tries++<3){if(d.type===Hls.ErrorTypes.MEDIA_ERROR)player.recoverMediaError();else setTimeout(()=>player?.startLoad(),2000);}else{player.destroy();player=null;playing=false;notice('توقف المصدر. ننتظر عودته؛ يمكنك إعادة التشغيل.');}});player.loadSource('/live/dshoof.m3u8');player.attachMedia(v);}else if(v.canPlayType('application/vnd.apple.mpegurl')){v.src='/live/dshoof.m3u8';v.play().catch(()=>{});}else notice('المتصفح لا يدعم HLS');}
async function refresh(){try{const s=await api('/api/status');authorized=s.authorized;currentSelection=s.selection;for(const id of ['owner-controls','receiver','friends'])$(id).hidden=!s.canControl;$('guest-controls').hidden=s.canControl;$('title').textContent=s.selection?.title||'دشوف مباشر';$('status').textContent=s.limited?'اكتمل عدد المشاهدين':s.ready?'البث جاهز للمشاهدة':s.status;if(!s.authorized&&playing){player?.destroy();player=null;$('video').pause();$('video').removeAttribute('src');$('video').load();$('youtube').removeAttribute('src');$('youtube').hidden=true;playing=false;notice('انتهت صلاحية المشاهدة أو اكتمل العدد');}const changed=lastSelection!==s.selection?.updatedAt;if(changed&&s.selection?.kind!=='youtube'&&!$('youtube').hidden){$('youtube').removeAttribute('src');$('youtube').hidden=true;playing=false;}if(s.ready&&authorized&&((!lastReady&&!playing)||(changed&&(s.selection?.kind==='youtube'||!playing))))watch();lastSelection=s.selection?.updatedAt;lastReady=s.ready;if(s.canControl){$('youtube-note').hidden=s.selection?.kind!=='youtube';$('playlist').value=s.playlist;$('download-playlist').href=s.playlist;$('selected-title').textContent=s.selection?.title||'لم يُحفظ بث بعد';$('viewers').textContent='المشاهدون الآن: '+s.viewers+' من '+s.maxViewers;$('invites').replaceChildren(...s.invites.map(x=>{const b=document.createElement('button');b.textContent=x.name+' · '+new Date(x.expires).toLocaleString('ar-IQ')+' · إلغاء';b.onclick=async()=>{try{await api('/api/revoke',{id:x.id});await refresh();}catch(e){notice(e.message)}};return b}));}}catch(e){$('status').textContent='تعذر الاتصال بالموقع؛ نحاول مجددًا';}}
